import json, glob
path = 'C:/Users/mushj/OneDrive/Desktop/ColumbiaU MSDS/S26 - STATGR5293 - GenAI with LLMs/Final Project/optimized-llm-planning-memory/data/user_requests'
transport_constraints = []
preference_values = set()
for f in glob.glob(path + '/**/*.json', recursive=True):
    try:
        data = json.load(open(f))
        for c in data.get('soft_constraints', []) + data.get('hard_constraints', []):
            if c.get('category') == 'transport':
                transport_constraints.append((f.split('/')[-1], c))
            if c.get('category') == 'preference':
                preference_values.add(str(c.get('value', '')))
    except: pass
print('TRANSPORT constraints:', len(transport_constraints))
for name, c in transport_constraints[:5]:
    print(f'  {name}: value={c[\"value\"]!r}, unit={c.get(\"unit\")!r}')
print()
print('PREFERENCE values:', sorted(preference_values))
